/// <summary>
/// PaffH 22.11.21
/// fill NameAlias
/// </summary>
void setNameAlias()
{
    NDXDirPartyTableBaseType::CreateInstance(this).setNameAlias();

    next setNameAlias();
}

/// <summary>
/// PaffH 14.08.25
/// </summary>
/// <returns>primary address as line</returns>
[SysClientCacheDataMethod]
display LogisticsAddressing NDXPrimaryAddressAsLine()
{
    return strReplace(this.primaryAddress(), NDXGlobalConstants::NewLine, NDXGlobalConstants::SemikolonSpace);
}

/// <summary>
/// PaffH 22.09.25
/// </summary>
/// <returns>dirPartyTable with empty name (for lookup)</returns>
public static DirPartyTable NDXfindOrCreateByNameEmpty()
{
    DirPartyTable dirPartyTable;
    select firstonly dirPartyTable where dirPartyTable.Name == '';
    if (!dirPartyTable)
    {
        dirPartyTable.initValue();
        dirPartyTable.NameAlias = 'EmptyName';
        dirPartyTable.insert();
    }
    return dirPartyTable;
}
